"use client"

import * as React from "react"
import { Check, Copy, Maximize, Minus, Plus } from "lucide-react"
import { createRoot, type Root } from "react-dom/client"

import type { ViewerResource } from "@/lib/viewer-resource"

import { Button } from "./button"
import {
  createMarkdownLayoutStyle,
  createMarkdownPageEstimates,
  MARKDOWN_DOCUMENT_PAGE_PADDING_X,
  MARKDOWN_DOCUMENT_PAGE_PADDING_Y,
  MARKDOWN_DOCUMENT_PAGE_WIDTH,
} from "./markdown-document-layout"
import {
  createMarkdownDocument,
  findMarkdownPageForLine,
  markdownPageIntersectsLineRange,
  type MarkdownDocument,
  type MarkdownDocumentPage,
} from "./markdown-document-model"
import { MarkdownDocumentPageRenderer } from "./markdown-document-renderer"
import { patchMarkdownPageTables } from "./markdown-document-table-accessibility"
import {
  createMarkdownVirtualGeometry,
  getMarkdownScrollAnchor,
  getMarkdownVirtualItems,
  scrollTopForMarkdownAnchor,
  topForMarkdownIndex,
  type MarkdownVirtualItem,
} from "./markdown-document-virtualizer"
import { PlainTextViewerShell } from "./plain-text-viewer-shell"
import { ScrollArea } from "./scroll-area"
import { Separator } from "./separator"
import { Tabs, TabsList, TabsTrigger } from "./tabs"
import { TextViewerFallback, TextViewerFrame } from "./text-viewer-chrome"
import { normalizeTextLineRange } from "./text-viewer-ranges"
import {
  readTextResource,
  resolvedTextViewerBounds,
} from "./text-viewer-resource"
import { clampTextViewerScale } from "./text-viewer-scale"
import type { TextViewerHandle, TextViewerProps } from "./text-viewer-types"
import { ViewerDownloadControl } from "./viewer-download"

const MARKDOWN_VIEWER_OVERSCAN_PX = 900
const MARKDOWN_VIEWER_DEFAULT_VIEWPORT_HEIGHT = 720
const MARKDOWN_VIEWER_DEFAULT_VIEWPORT_WIDTH = 960
const MARKDOWN_VIEWER_CANVAS_PADDING_Y = 16
const MARKDOWN_VIEWER_FIT_PADDING_X = 32
const MARKDOWN_VIEWER_PAGE_GAP = 16
const MARKDOWN_VIEWER_READING_SCALE = 0.75
const MARKDOWN_VIEWER_ZOOM_STEP = 1.2

type MarkdownDocumentViewMode = "rendered" | "text"

type ViewportSize = {
  height: number
  width: number
}

const MarkdownProjectionCanvas = React.forwardRef<HTMLDivElement>(
  function MarkdownProjectionCanvas(_, ref) {
    return (
      <div
        ref={ref}
        className="relative mx-auto min-w-0"
        data-slot="markdown-document-virtual-canvas"
      />
    )
  }
)

export const MarkdownDocumentViewer = React.forwardRef<
  TextViewerHandle,
  TextViewerProps
>(function MarkdownDocumentViewer(props, ref) {
  return (
    <PlainTextViewerShell
      props={props}
      forwardedRef={ref}
      clientFallbackPolicy="always"
      Fallback={TextViewerFallback}
      Content={MarkdownDocumentViewerContent}
    />
  )
})

function MarkdownDocumentViewerContent({
  resource,
  className,
  toolbar = true,
  highlight,
  bare = false,
  maxBytes,
  maxLines,
  retryVersion,
  forwardedRef,
}: TextViewerProps & {
  resource: ViewerResource
  retryVersion: number
  forwardedRef?: React.ForwardedRef<TextViewerHandle>
}) {
  const bounds = React.useMemo(
    () => resolvedTextViewerBounds({ maxBytes, maxLines }),
    [maxBytes, maxLines]
  )
  const text = React.useMemo(
    () =>
      readTextResource({
        bounds,
        content: resource.content,
        retryVersion,
      }),
    [bounds, resource.content, retryVersion]
  )
  const document = React.useMemo(() => createMarkdownDocument(text), [text])
  const [mode, setMode] = React.useState<MarkdownDocumentViewMode>("rendered")
  const [manualScale, setManualScale] = React.useState<number | null>(null)
  const [currentPage, setCurrentPage] = React.useState(1)
  const [viewportSize, setViewportSize] = React.useState<ViewportSize>({
    height: 0,
    width: 0,
  })
  const [measuredHeights, setMeasuredHeights] = React.useState<
    Map<string, number>
  >(() => new Map())
  const canvasRef = React.useRef<HTMLDivElement | null>(null)
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const scrollFrameRef = React.useRef<number | null>(null)
  const scrollTopRef = React.useRef(0)
  const projectionCacheRef = React.useRef<MarkdownProjectionCache>({
    measurementKey: "",
    pages: new Map(),
  })
  const pendingAnchorRef = React.useRef<ReturnType<
    typeof getMarkdownScrollAnchor
  > | null>(null)
  const viewportHeight =
    viewportSize.height || MARKDOWN_VIEWER_DEFAULT_VIEWPORT_HEIGHT
  const viewportWidth =
    viewportSize.width || MARKDOWN_VIEWER_DEFAULT_VIEWPORT_WIDTH
  const fitScale = React.useMemo(
    () => getMarkdownDocumentFitScale(viewportWidth),
    [viewportWidth]
  )
  const scale = manualScale ?? fitScale
  const highlightRange = React.useMemo(
    () => normalizeTextLineRange(highlight, document.lineCount),
    [document.lineCount, highlight]
  )
  const pageMeasurementKey = React.useMemo(
    () => `${mode}:${scale.toFixed(3)}:${viewportWidth}:${text.length}`,
    [mode, scale, text.length, viewportWidth]
  )
  const pageEstimates = React.useMemo(
    () =>
      createMarkdownPageEstimates(
        document,
        createMarkdownLayoutStyle({
          contentWidth: MARKDOWN_DOCUMENT_PAGE_WIDTH * scale,
          zoom: scale,
        })
      ),
    [document, scale]
  )
  const estimateHeight = React.useCallback(
    (index: number) => (pageEstimates[index] ?? 1) + MARKDOWN_VIEWER_PAGE_GAP,
    [pageEstimates]
  )
  const getKey = React.useCallback(
    (index: number) =>
      `${pageMeasurementKey}:${document.pages[index]?.id ?? index}`,
    [document.pages, pageMeasurementKey]
  )
  const virtualGeometry = React.useMemo(
    () =>
      createMarkdownVirtualGeometry({
        count: document.pages.length,
        estimateHeight,
        getKey,
        measuredHeights,
      }),
    [document.pages.length, estimateHeight, getKey, measuredHeights]
  )
  React.useEffect(() => {
    setMeasuredHeights(new Map())
  }, [pageMeasurementKey])

  React.useEffect(() => {
    pendingAnchorRef.current = null
    setManualScale(null)
    setCurrentPage(1)
    scrollTopRef.current = 0
    scrollMarkdownViewportTo(viewportRef.current, { left: 0, top: 0 })
  }, [document])

  const readVirtualScrollTop = React.useCallback(() => {
    return Math.max(
      0,
      (viewportRef.current?.scrollTop ?? scrollTopRef.current) -
        MARKDOWN_VIEWER_CANVAS_PADDING_Y
    )
  }, [])

  const captureScrollAnchor = React.useCallback(() => {
    pendingAnchorRef.current = getMarkdownScrollAnchor({
      geometry: virtualGeometry,
      scrollTop: readVirtualScrollTop(),
    })
  }, [readVirtualScrollTop, virtualGeometry])

  React.useLayoutEffect(() => {
    const anchor = pendingAnchorRef.current
    const viewport = viewportRef.current
    if (!anchor || !viewport) return

    pendingAnchorRef.current = null
    const nextVirtualScrollTop = scrollTopForMarkdownAnchor({
      anchor,
      geometry: virtualGeometry,
    })
    viewport.scrollTop = nextVirtualScrollTop + MARKDOWN_VIEWER_CANVAS_PADDING_Y
    scrollTopRef.current = viewport.scrollTop
  }, [virtualGeometry])

  React.useLayoutEffect(() => {
    const viewport = viewportRef.current
    if (!viewport) return

    const readSize = () => {
      setViewportSize((current) => {
        const next = {
          height: viewport.clientHeight,
          width: viewport.clientWidth,
        }
        return current.height === next.height && current.width === next.width
          ? current
          : next
      })
    }

    readSize()
    const observer =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(readSize)
    observer?.observe(viewport)
    return () => observer?.disconnect()
  }, [])

  const measurePage = React.useCallback(
    (key: string, height: number) => {
      if (!Number.isFinite(height) || height <= 0) return

      setMeasuredHeights((current) => {
        if (current.get(key) === height) return current
        captureScrollAnchor()
        const next = new Map(current)
        next.set(key, height)
        return next
      })
    },
    [captureScrollAnchor]
  )

  const projectPages = React.useCallback(() => {
    scrollFrameRef.current = null
    const nextPage = projectMarkdownPages({
      cache: projectionCacheRef.current,
      canvas: canvasRef.current,
      document,
      geometry: virtualGeometry,
      highlightRange,
      measurePage,
      measurementKey: pageMeasurementKey,
      mode,
      scale,
      viewport: viewportRef.current,
      viewportHeight,
    })

    setCurrentPage((page) => (page === nextPage ? page : nextPage))
  }, [
    document,
    virtualGeometry,
    highlightRange,
    measurePage,
    mode,
    pageMeasurementKey,
    scale,
    viewportHeight,
  ])

  const scheduleProjectPages = React.useCallback(() => {
    if (scrollFrameRef.current !== null) return
    if (typeof requestAnimationFrame === "undefined") {
      projectPages()
      return
    }
    scrollFrameRef.current = requestAnimationFrame(projectPages)
  }, [projectPages])

  const handleScroll = React.useCallback(() => {
    scrollTopRef.current = viewportRef.current?.scrollTop ?? 0
    scheduleProjectPages()
  }, [scheduleProjectPages])

  React.useLayoutEffect(() => {
    projectPages()
  }, [projectPages])

  React.useEffect(
    () => () => {
      if (
        scrollFrameRef.current !== null &&
        typeof cancelAnimationFrame !== "undefined"
      ) {
        cancelAnimationFrame(scrollFrameRef.current)
      }
      disposeMarkdownProjectionCache(projectionCacheRef.current)
    },
    []
  )

  const scrollToPageIndex = React.useCallback(
    (index: number, options?: ScrollToOptions, sourceLine?: number) => {
      const viewport = viewportRef.current
      if (!viewport || document.pages.length === 0) return
      const page = document.pages[index]
      const lineOffset =
        page && sourceLine
          ? Math.max(0, sourceLine - page.pageStartLine) * 24 * scale
          : 0
      const targetTop =
        MARKDOWN_VIEWER_CANVAS_PADDING_Y +
        topForMarkdownIndex({
          geometry: virtualGeometry,
          index,
        }) +
        lineOffset
      const maxTop =
        MARKDOWN_VIEWER_CANVAS_PADDING_Y +
        Math.max(0, virtualGeometry.totalHeight - viewport.clientHeight)
      const top = Math.min(maxTop, Math.max(0, targetTop))
      scrollMarkdownViewportTo(viewport, {
        behavior: "smooth",
        top,
        ...options,
      })
      scrollTopRef.current = top
      projectPages()
    },
    [document.pages, projectPages, scale, virtualGeometry]
  )

  const scrollToLineRange = React.useCallback(
    (
      range: ReturnType<typeof normalizeTextLineRange>,
      options?: ScrollToOptions
    ) => {
      if (!range) return
      const page = findMarkdownPageForLine(document.pages, range.start)
      if (!page) return
      scrollToPageIndex(page.pageNumber - 1, options, range.start)
    },
    [document.pages, scrollToPageIndex]
  )

  React.useImperativeHandle(
    forwardedRef,
    () => ({
      getViewportElement: () => viewportRef.current,
      scrollToLineRange: (range, options) => {
        scrollToLineRange(
          normalizeTextLineRange(range, document.lineCount),
          options
        )
      },
    }),
    [document.lineCount, scrollToLineRange]
  )

  React.useEffect(() => {
    scrollToLineRange(highlightRange)
  }, [highlightRange, scrollToLineRange])

  const zoom = (factor: number) => {
    captureScrollAnchor()
    setManualScale(clampTextViewerScale(scale * factor))
  }
  const fitWidth = () => {
    captureScrollAnchor()
    setManualScale(null)
  }
  const resetZoom = () => {
    captureScrollAnchor()
    setManualScale(1)
  }
  const handleFragmentClick = React.useCallback(
    (event: React.MouseEvent) => {
      const href = localFragmentHrefFromEventTarget(event.target)
      if (!href) return

      const targetId = decodeFragmentHref(href)
      const targetPage = document.pages.find((page) =>
        page.blocks.some((block) => block.headingId === targetId)
      )
      if (!targetPage) return

      event.preventDefault()
      const targetLine =
        targetPage.blocks.find((block) => block.headingId === targetId)
          ?.blockStartLine ?? targetPage.pageStartLine
      scrollToPageIndex(targetPage.pageNumber - 1, undefined, targetLine)
      if (window.location.hash !== href) {
        window.history.replaceState(null, "", href)
      }
    },
    [document.pages, scrollToPageIndex]
  )

  return (
    <TextViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <MarkdownDocumentToolbar
          currentPage={currentPage}
          document={document}
          downloadAction={resource.originalDownload}
          mode={mode}
          scale={scale}
          onFitWidth={fitWidth}
          onModeChange={setMode}
          onResetZoom={resetZoom}
          onZoomIn={() => zoom(MARKDOWN_VIEWER_ZOOM_STEP)}
          onZoomOut={() => zoom(1 / MARKDOWN_VIEWER_ZOOM_STEP)}
        />
      ) : null}
      <ScrollArea
        className="min-h-0 flex-1 bg-muted/30"
        orientation="vertical"
        viewportClassName="bg-muted/30"
        viewportProps={{
          onClickCapture: handleFragmentClick,
          onScroll: handleScroll,
        }}
        viewportRef={viewportRef}
      >
        <MarkdownProjectionCanvas ref={canvasRef} />
      </ScrollArea>
    </TextViewerFrame>
  )
}

function MarkdownDocumentToolbar({
  currentPage,
  document,
  downloadAction,
  mode,
  scale,
  onFitWidth,
  onModeChange,
  onResetZoom,
  onZoomIn,
  onZoomOut,
}: {
  currentPage: number
  document: MarkdownDocument
  downloadAction: NonNullable<ViewerResource["originalDownload"]>
  mode: MarkdownDocumentViewMode
  scale: number
  onFitWidth: () => void
  onModeChange: (mode: MarkdownDocumentViewMode) => void
  onResetZoom: () => void
  onZoomIn: () => void
  onZoomOut: () => void
}) {
  return (
    <div className="no-scrollbar flex h-10 shrink-0 items-center gap-2 overflow-x-auto border-b bg-card px-2">
      <span className="px-1 text-xs whitespace-nowrap text-muted-foreground tabular-nums">
        Page {currentPage} of {document.pages.length}
      </span>
      <Tabs
        value={mode}
        onValueChange={(value) =>
          onModeChange(value as MarkdownDocumentViewMode)
        }
      >
        <TabsList variant="underline" className="py-0">
          <TabsTrigger value="rendered" className="h-8 text-xs sm:text-xs">
            Rendered
          </TabsTrigger>
          <TabsTrigger value="text" className="h-8 text-xs sm:text-xs">
            Text
          </TabsTrigger>
        </TabsList>
      </Tabs>
      <div className="ml-auto flex shrink-0 items-center gap-1">
        <ToolbarIconButton label="Zoom out" onClick={onZoomOut}>
          <Minus />
        </ToolbarIconButton>
        <button
          className="w-12 text-center text-xs text-muted-foreground tabular-nums"
          title="Reset zoom"
          type="button"
          onClick={onResetZoom}
        >
          {Math.round(scale * 100)}%
        </button>
        <ToolbarIconButton label="Zoom in" onClick={onZoomIn}>
          <Plus />
        </ToolbarIconButton>
        <ToolbarIconButton label="Fit width" onClick={onFitWidth}>
          <Maximize />
        </ToolbarIconButton>
        <Separator orientation="vertical" className="mx-1 h-4" />
        <CopyAllMarkdownButton text={document.text} />
        <ViewerDownloadControl actions={[downloadAction]} />
      </div>
    </div>
  )
}

function CopyAllMarkdownButton({ text }: { text: string }) {
  const [isCopied, setIsCopied] = React.useState(false)
  const timeoutRef = React.useRef<number | null>(null)

  React.useEffect(
    () => () => {
      if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)
    },
    []
  )

  const copy = () => {
    if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)
    void navigator.clipboard?.writeText(text).then(() => {
      setIsCopied(true)
      timeoutRef.current = window.setTimeout(() => {
        timeoutRef.current = null
        setIsCopied(false)
      }, 1200)
    })
  }

  return (
    <Button
      aria-label={isCopied ? "Copied" : "Copy markdown"}
      className="size-7"
      size="icon-sm"
      title="Copy markdown"
      type="button"
      variant="ghost"
      onClick={copy}
    >
      {isCopied ? <Check /> : <Copy />}
    </Button>
  )
}

function ToolbarIconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      aria-label={label}
      className="size-7"
      size="icon-sm"
      title={label}
      type="button"
      variant="ghost"
      {...props}
    >
      {children}
    </Button>
  )
}

type MarkdownProjectionCache = {
  measurementKey: string
  pages: Map<string, MarkdownProjectedPage>
}

type MarkdownProjectedPage = {
  renderKey: string
  resizeObserver: ResizeObserver | null
  root: Root
  shell: HTMLElement
}

function projectMarkdownPages({
  cache,
  canvas,
  document,
  geometry,
  highlightRange,
  measurePage,
  measurementKey,
  mode,
  scale,
  viewport,
  viewportHeight,
}: {
  cache: MarkdownProjectionCache
  canvas: HTMLDivElement | null
  document: MarkdownDocument
  geometry: ReturnType<typeof createMarkdownVirtualGeometry>
  highlightRange: ReturnType<typeof normalizeTextLineRange>
  measurePage: (key: string, height: number) => void
  measurementKey: string
  mode: MarkdownDocumentViewMode
  scale: number
  viewport: HTMLDivElement | null
  viewportHeight: number
}) {
  if (!canvas) return 1

  canvas.style.height = `${
    geometry.totalHeight + MARKDOWN_VIEWER_CANVAS_PADDING_Y * 2
  }px`
  canvas.style.width = `${Math.max(1, MARKDOWN_DOCUMENT_PAGE_WIDTH * scale)}px`

  if (cache.measurementKey !== measurementKey) {
    disposeMarkdownProjectionCache(cache)
    cache.measurementKey = measurementKey
  }

  const scrollTop = Math.max(
    0,
    (viewport?.scrollTop ?? 0) - MARKDOWN_VIEWER_CANVAS_PADDING_Y
  )
  const virtualWindow = getMarkdownVirtualItems({
    geometry,
    overscanPx: MARKDOWN_VIEWER_OVERSCAN_PX,
    scrollTop,
    viewportHeight,
  })
  const visibleKeys = new Set(
    virtualWindow.items.map((virtualItem) => virtualItem.key)
  )

  for (const [key, projectedPage] of cache.pages) {
    if (visibleKeys.has(key)) continue
    disposeMarkdownProjectedPage(projectedPage)
    cache.pages.delete(key)
  }

  for (const virtualItem of virtualWindow.items) {
    const page = document.pages[virtualItem.index]
    if (!page) continue
    const projectedPage =
      cache.pages.get(virtualItem.key) ??
      createMarkdownProjectedPage({
        cache,
        key: virtualItem.key,
        measurePage,
        page,
      })

    patchMarkdownPageShell({
      highlightRange,
      page,
      projectedPage,
      scale,
      virtualItem,
    })
    renderMarkdownProjectedPage({
      document,
      highlightRange,
      measurePage,
      mode,
      page,
      projectedPage,
      virtualItem,
    })
    canvas.append(projectedPage.shell)
  }

  return currentPageFromVirtualItems({
    items: virtualWindow.items,
    pages: document.pages,
    scrollTop,
  })
}

function createMarkdownProjectedPage({
  cache,
  key,
  measurePage,
  page,
}: {
  cache: MarkdownProjectionCache
  key: string
  measurePage: (key: string, height: number) => void
  page: MarkdownDocumentPage
}) {
  const shell = document.createElement("article")
  const projectedPage: MarkdownProjectedPage = {
    renderKey: "",
    resizeObserver:
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(() =>
            syncMarkdownProjectedPage({
              measurePage,
              page,
              pageMeasurementKey: key,
              projectedPage,
            })
          ),
    root: createRoot(shell),
    shell,
  }
  projectedPage.resizeObserver?.observe(shell)
  cache.pages.set(key, projectedPage)
  return projectedPage
}

function patchMarkdownPageShell({
  highlightRange,
  page,
  projectedPage,
  scale,
  virtualItem,
}: {
  highlightRange: ReturnType<typeof normalizeTextLineRange>
  page: MarkdownDocumentPage
  projectedPage: MarkdownProjectedPage
  scale: number
  virtualItem: MarkdownVirtualItem
}) {
  const isHighlighted = markdownPageIntersectsLineRange({
    page,
    range: highlightRange,
  })
  projectedPage.shell.ariaCurrent = isHighlighted ? "true" : null
  projectedPage.shell.className = `absolute bg-card text-card-foreground shadow-sm ring-1 ring-border ${
    isHighlighted ? "ring-primary/40" : ""
  }`
  projectedPage.shell.dataset.pageNumber = String(page.pageNumber)
  projectedPage.shell.dataset.slot = "markdown-document-page"
  projectedPage.shell.dataset.sourceEndLine = String(page.pageEndLine)
  projectedPage.shell.dataset.sourceLine = String(page.pageStartLine)
  projectedPage.shell.style.fontSize = `${14 * scale}px`
  projectedPage.shell.style.left = "50%"
  projectedPage.shell.style.minHeight = `${Math.max(
    1,
    virtualItem.height - MARKDOWN_VIEWER_PAGE_GAP
  )}px`
  projectedPage.shell.style.paddingBlock = `${
    MARKDOWN_DOCUMENT_PAGE_PADDING_Y * scale
  }px`
  projectedPage.shell.style.paddingInline = `${
    MARKDOWN_DOCUMENT_PAGE_PADDING_X * scale
  }px`
  projectedPage.shell.style.transform = `translate(-50%, ${
    virtualItem.top + MARKDOWN_VIEWER_CANVAS_PADDING_Y
  }px)`
  projectedPage.shell.style.width = `${MARKDOWN_DOCUMENT_PAGE_WIDTH * scale}px`
}

function renderMarkdownProjectedPage({
  document,
  highlightRange,
  measurePage,
  mode,
  page,
  projectedPage,
  virtualItem,
}: {
  document: MarkdownDocument
  highlightRange: ReturnType<typeof normalizeTextLineRange>
  measurePage: (key: string, height: number) => void
  mode: MarkdownDocumentViewMode
  page: MarkdownDocumentPage
  projectedPage: MarkdownProjectedPage
  virtualItem: MarkdownVirtualItem
}) {
  const renderKey = [
    virtualItem.key,
    mode,
    page.id,
    page.markdown,
    highlightRange?.start ?? "",
    highlightRange?.end ?? "",
  ].join("\u0000")
  if (projectedPage.renderKey === renderKey) return

  projectedPage.renderKey = renderKey
  const syncPage = () =>
    syncMarkdownProjectedPage({
      measurePage,
      page,
      pageMeasurementKey: virtualItem.key,
      projectedPage,
    })
  projectedPage.root.render(
    <MarkdownVirtualPageContent
      document={document}
      highlightRange={highlightRange}
      mode={mode}
      page={page}
      onContentReady={syncPage}
    />
  )
}

function syncMarkdownProjectedPage({
  measurePage,
  page,
  pageMeasurementKey,
  projectedPage,
}: {
  measurePage: (key: string, height: number) => void
  page: MarkdownDocumentPage
  pageMeasurementKey: string
  projectedPage: MarkdownProjectedPage
}) {
  patchMarkdownPageTables({ pageId: page.id, root: projectedPage.shell })
  const content = projectedPage.shell.querySelector<HTMLElement>(
    '[data-slot="markdown-document-rendered-content"], [data-slot="markdown-document-text-content"]'
  )
  const measuredElement = content ?? projectedPage.shell
  const height =
    measuredElement.offsetHeight ||
    measuredElement.getBoundingClientRect().height
  if (!Number.isFinite(height) || height <= 0) return
  measurePage(pageMeasurementKey, height + MARKDOWN_VIEWER_PAGE_GAP)
}

function disposeMarkdownProjectionCache(cache: MarkdownProjectionCache) {
  for (const projectedPage of cache.pages.values()) {
    disposeMarkdownProjectedPage(projectedPage)
  }
  cache.pages.clear()
}

function disposeMarkdownProjectedPage(projectedPage: MarkdownProjectedPage) {
  projectedPage.resizeObserver?.disconnect()
  deferMarkdownRootUnmount(projectedPage.root)
  projectedPage.shell.remove()
}

function deferMarkdownRootUnmount(root: Root) {
  const unmount = () => root.unmount()
  if (typeof queueMicrotask === "function") {
    queueMicrotask(unmount)
    return
  }
  window.setTimeout(unmount, 0)
}

function MarkdownVirtualPageContent({
  document,
  highlightRange,
  mode,
  page,
  onContentReady,
}: {
  document: MarkdownDocument
  highlightRange: ReturnType<typeof normalizeTextLineRange>
  mode: MarkdownDocumentViewMode
  page: MarkdownDocumentPage
  onContentReady: () => void
}) {
  React.useLayoutEffect(() => {
    onContentReady()
  }, [onContentReady])

  return mode === "text" ? (
    <pre
      className="font-mono leading-relaxed whitespace-pre-wrap text-foreground/90"
      data-slot="markdown-document-text-content"
    >
      {page.markdown}
    </pre>
  ) : (
    <MarkdownDocumentPageRenderer
      headingIdsByLine={document.headingIdsByLine}
      highlightRange={highlightRange}
      onContentReady={onContentReady}
      page={page}
    />
  )
}

function getMarkdownDocumentFitScale(viewportWidth: number) {
  const availableWidth = viewportWidth - MARKDOWN_VIEWER_FIT_PADDING_X
  const fitWidthScale = availableWidth / MARKDOWN_DOCUMENT_PAGE_WIDTH
  return clampTextViewerScale(
    Math.min(MARKDOWN_VIEWER_READING_SCALE, fitWidthScale)
  )
}

function scrollMarkdownViewportTo(
  viewport: HTMLElement | null,
  options: ScrollToOptions
) {
  if (!viewport) return
  if (typeof viewport.scrollTo === "function") {
    viewport.scrollTo(options)
    return
  }
  if (typeof options.left === "number") viewport.scrollLeft = options.left
  if (typeof options.top === "number") viewport.scrollTop = options.top
}

function currentPageFromVirtualItems({
  items,
  pages,
  scrollTop,
}: {
  items: readonly MarkdownVirtualItem[]
  pages: readonly MarkdownDocumentPage[]
  scrollTop: number
}) {
  const currentVirtualItem =
    items.find((virtualItem) => virtualItem.bottom >= scrollTop + 80) ??
    items[0]
  return pages[currentVirtualItem?.index ?? 0]?.pageNumber ?? 1
}

function localFragmentHrefFromEventTarget(target: EventTarget | null) {
  if (!(target instanceof Element)) return null
  const link = target.closest<HTMLAnchorElement>('a[href^="#"]')
  const href = link?.getAttribute("href") ?? null
  return href && href.length > 1 ? href : null
}

function decodeFragmentHref(href: string) {
  try {
    return decodeURIComponent(href.slice(1))
  } catch {
    return href.slice(1)
  }
}

import { measureLineStats, prepareWithSegments } from "@chenglou/pretext"

import type {
  MarkdownDocument,
  MarkdownDocumentBlock,
  MarkdownDocumentBlockKind,
  MarkdownDocumentPage,
} from "./markdown-document-model"
import { splitTextLines } from "./text-viewer-resource"

export const MARKDOWN_DOCUMENT_PAGE_WIDTH = 768
export const MARKDOWN_DOCUMENT_PAGE_PADDING_X = 36
export const MARKDOWN_DOCUMENT_PAGE_PADDING_Y = 28
export const MARKDOWN_DOCUMENT_TARGET_PAGE_HEIGHT = 980
export const MARKDOWN_DOCUMENT_MIN_PAGE_HEIGHT = 220
export const MARKDOWN_DOCUMENT_MAX_ESTIMATED_PAGE_HEIGHT = 2200

const MARKDOWN_DOCUMENT_BODY_FONT =
  '14px ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
const MARKDOWN_DOCUMENT_CODE_FONT =
  '13px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace'
const MARKDOWN_DOCUMENT_STYLE_VERSION = "markdown-document-layout-v1"

export type MarkdownDocumentLayoutStyle = {
  blockSpacing: number
  bodyFont: string
  bodyLineHeight: number
  codeFont: string
  codeLineHeight: number
  contentWidth: number
  pagePaddingX: number
  pagePaddingY: number
  styleVersion: string
  zoom: number
}

export function createMarkdownLayoutStyle({
  contentWidth = MARKDOWN_DOCUMENT_PAGE_WIDTH,
  zoom = 1,
}: {
  contentWidth?: number
  zoom?: number
} = {}): MarkdownDocumentLayoutStyle {
  return {
    blockSpacing: 14 * zoom,
    bodyFont: MARKDOWN_DOCUMENT_BODY_FONT,
    bodyLineHeight: 26 * zoom,
    codeFont: MARKDOWN_DOCUMENT_CODE_FONT,
    codeLineHeight: 22 * zoom,
    contentWidth: Math.max(1, contentWidth),
    pagePaddingX: MARKDOWN_DOCUMENT_PAGE_PADDING_X * zoom,
    pagePaddingY: MARKDOWN_DOCUMENT_PAGE_PADDING_Y * zoom,
    styleVersion: MARKDOWN_DOCUMENT_STYLE_VERSION,
    zoom,
  }
}

export function estimateMarkdownBlockHeight(
  block: Pick<MarkdownDocumentBlock, "kind" | "markdown">,
  style: MarkdownDocumentLayoutStyle
) {
  switch (block.kind) {
    case "heading":
      return (
        estimateFlowTextHeight(block.markdown, style, 1.25) + 18 * style.zoom
      )
    case "rule":
      return 34 * style.zoom
    case "code":
      return estimateCodeHeight(block.markdown, style)
    case "callout":
      return Math.max(
        96 * style.zoom,
        estimateFlowTextHeight(stripMarkdownSyntax(block.markdown), style, 1) +
          44 * style.zoom
      )
    case "math":
      return Math.max(
        86 * style.zoom,
        countRawLines(block.markdown) * 28 * style.zoom + 42 * style.zoom
      )
    case "table":
      return estimateTableHeight(block.markdown, style)
    case "image":
      return 260 * style.zoom
    case "list":
      return Math.max(
        72 * style.zoom,
        estimateFlowTextHeight(stripMarkdownSyntax(block.markdown), style, 1) +
          24 * style.zoom
      )
    case "blockquote":
      return Math.max(
        72 * style.zoom,
        estimateFlowTextHeight(stripMarkdownSyntax(block.markdown), style, 1) +
          24 * style.zoom
      )
    case "html":
      return Math.max(
        56 * style.zoom,
        countRawLines(block.markdown) * 24 * style.zoom + 20 * style.zoom
      )
    case "paragraph":
      return (
        estimateFlowTextHeight(stripMarkdownSyntax(block.markdown), style, 1) +
        24 * style.zoom
      )
  }
}

export function estimateMarkdownPageHeight(
  page: MarkdownDocumentPage,
  style: MarkdownDocumentLayoutStyle
) {
  return clampMarkdownPageHeight(
    style.pagePaddingY * 2 +
      page.blocks.reduce(
        (height, block) =>
          height +
          estimateMarkdownBlockHeight(block, style) +
          style.blockSpacing,
        0
      )
  )
}

export function createMarkdownPageEstimates(
  document: MarkdownDocument,
  style: MarkdownDocumentLayoutStyle
) {
  return document.pages.map((page) => estimateMarkdownPageHeight(page, style))
}

export function createEstimatedMarkdownBlock({
  kind,
  markdown,
}: {
  kind: MarkdownDocumentBlockKind
  markdown: string
}) {
  return {
    estimatedHeight: estimateMarkdownBlockHeight(
      { kind, markdown },
      createMarkdownLayoutStyle()
    ),
    isHostile: isHostileMarkdownBlock({ kind, markdown }),
  }
}

export function pageChromeHeight() {
  return MARKDOWN_DOCUMENT_PAGE_PADDING_Y * 2
}

export function clampMarkdownPageHeight(height: number) {
  return Math.min(
    MARKDOWN_DOCUMENT_MAX_ESTIMATED_PAGE_HEIGHT,
    Math.max(MARKDOWN_DOCUMENT_MIN_PAGE_HEIGHT, height)
  )
}

export function isHostileMarkdownBlock({
  kind,
  markdown,
}: Pick<MarkdownDocumentBlock, "kind" | "markdown">) {
  const lineCount = countRawLines(markdown)

  switch (kind) {
    case "code":
      return lineCount > 400
    case "table":
      return Math.max(0, lineCount - 2) > 200
    case "paragraph":
      return markdown.length > 20_000
    case "list":
      return lineCount > 500
    case "html":
      return markdown.length > 20_000
    default:
      return false
  }
}

function estimateFlowTextHeight(
  markdown: string,
  style: MarkdownDocumentLayoutStyle,
  lineHeightMultiplier: number
) {
  const text = markdown.replace(/\s+/g, " ").trim() || " "
  const width = Math.max(1, style.contentWidth - style.pagePaddingX * 2)
  const lineHeight = style.bodyLineHeight * lineHeightMultiplier
  return (
    measurePretextLineCount({
      fallbackText: text,
      font: style.bodyFont,
      text,
      width,
    }) * lineHeight
  )
}

function estimateCodeHeight(
  markdown: string,
  style: MarkdownDocumentLayoutStyle
) {
  const code = fencedCodeBody(markdown)
  const width = Math.max(1, style.contentWidth - style.pagePaddingX * 2 - 32)
  return (
    Math.max(
      1,
      measurePretextLineCount({
        fallbackText: code,
        font: style.codeFont,
        text: code || " ",
        whiteSpace: "pre-wrap",
        width,
      })
    ) *
      style.codeLineHeight +
    58 * style.zoom
  )
}

function estimateTableHeight(
  markdown: string,
  style: MarkdownDocumentLayoutStyle
) {
  const rowCount = Math.max(1, countRawLines(markdown) - 2)
  return Math.max(96 * style.zoom, 48 * style.zoom + rowCount * 36 * style.zoom)
}

function measurePretextLineCount({
  fallbackText,
  font,
  text,
  whiteSpace,
  width,
}: {
  fallbackText: string
  font: string
  text: string
  whiteSpace?: "pre-wrap"
  width: number
}) {
  if (isJsdomRuntime()) return estimateLineCount(fallbackText, width)

  try {
    const prepared = prepareWithSegments(text, font, { whiteSpace })
    return Math.max(1, measureLineStats(prepared, Math.max(1, width)).lineCount)
  } catch {
    return estimateLineCount(fallbackText, width)
  }
}

function isJsdomRuntime() {
  return (
    globalThis.navigator?.userAgent.toLowerCase().includes("jsdom") ?? false
  )
}

function estimateLineCount(text: string, width: number) {
  const columns = Math.max(1, Math.floor(width / 8))
  return splitTextLines(text || " ").reduce(
    (sum, line) => sum + Math.max(1, Math.ceil((line || " ").length / columns)),
    0
  )
}

function stripMarkdownSyntax(markdown: string) {
  return markdown
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/^:::\w+(?:\{[^}]*\})?/gm, "")
    .replace(/^:::\s*$/gm, "")
    .replace(/[`*_~[\]()!>#|-]/g, " ")
}

function fencedCodeBody(markdown: string) {
  const lines = splitTextLines(markdown)
  if (lines.length >= 2 && /^```/.test(lines[0] ?? "")) {
    return lines.slice(1, -1).join("\n").replace(/\n$/, "")
  }
  return markdown.replace(/\n$/, "")
}

function countRawLines(raw: string) {
  return splitTextLines(raw.replace(/\r?\n$/, "")).length
}

"use client"

import * as React from "react"
import { MarkdownHooks } from "react-markdown"

import {
  type MarkdownDocumentPage,
  type MarkdownLineRange,
} from "./markdown-document-model"
import {
  MARKDOWN_DOCUMENT_REHYPE_PLUGINS,
  MARKDOWN_DOCUMENT_REMARK_PLUGINS,
} from "./markdown-document-plugins"
import { createMarkdownDocumentRenderers } from "./markdown-document-renderers"
import { sanitizeMarkdownUrl } from "./markdown-document-url-policy"

export function MarkdownDocumentPageRenderer({
  headingIdsByLine,
  highlightRange,
  onContentReady,
  page,
}: {
  headingIdsByLine: ReadonlyMap<number, string>
  highlightRange: MarkdownLineRange | null
  onContentReady?: () => void
  page: MarkdownDocumentPage
}) {
  const contentRef = React.useRef<HTMLDivElement | null>(null)
  const hasReportedReadyRef = React.useRef(false)
  const [renderState, setRenderState] = React.useState<"pending" | "ready">(
    "pending"
  )
  const components = React.useMemo(
    () =>
      createMarkdownDocumentRenderers({
        headingIdsByLine,
        highlightRange,
        page,
      }),
    [headingIdsByLine, highlightRange, page]
  )
  React.useLayoutEffect(() => {
    hasReportedReadyRef.current = false
    setRenderState("pending")
  }, [page.markdown])

  React.useLayoutEffect(() => {
    const content = contentRef.current
    if (!content) return

    const markReady = (forceMeasure = false) => {
      if (content.childNodes.length === 0) return
      if (!hasReportedReadyRef.current) {
        hasReportedReadyRef.current = true
        setRenderState("ready")
        onContentReady?.()
        return
      }
      if (forceMeasure) onContentReady?.()
    }

    markReady()
    const observer =
      typeof MutationObserver === "undefined"
        ? null
        : new MutationObserver(() => markReady(true))
    observer?.observe(content, {
      attributes: false,
      childList: true,
      subtree: true,
    })
    const readyCheckTimeout = window.setTimeout(() => markReady(true), 0)
    return () => {
      window.clearTimeout(readyCheckTimeout)
      observer?.disconnect()
    }
  }, [onContentReady, page.markdown])

  return (
    <div
      ref={contentRef}
      data-markdown-render-state={renderState}
      data-slot="markdown-document-rendered-content"
    >
      <MarkdownHooks
        rehypePlugins={MARKDOWN_DOCUMENT_REHYPE_PLUGINS}
        remarkPlugins={MARKDOWN_DOCUMENT_REMARK_PLUGINS}
        remarkRehypeOptions={{ allowDangerousHtml: true }}
        components={components}
        urlTransform={sanitizeMarkdownUrl}
      >
        {page.markdown}
      </MarkdownHooks>
    </div>
  )
}

export function markdownTableHeaderId(
  pageId: string,
  tableIndex: number,
  columnIndex: number
) {
  return `${pageId}-table-${tableIndex}-column-${columnIndex}`
}

export function patchMarkdownPageTables({
  pageId,
  root,
}: {
  pageId: string
  root: HTMLElement | null
}) {
  if (!root) return

  root
    .querySelectorAll<HTMLTableElement>("table[data-markdown-table]")
    .forEach((table, tableIndex) => {
      const headers = Array.from(table.querySelectorAll("thead th"))

      headers.forEach((header, columnIndex) => {
        header.id = markdownTableHeaderId(pageId, tableIndex, columnIndex)
        header.setAttribute("scope", "col")
      })

      table.querySelectorAll("tbody tr").forEach((row) => {
        Array.from(row.querySelectorAll<HTMLTableCellElement>("td")).forEach(
          (cell, columnIndex) => {
            const header = headers[columnIndex]
            if (header) cell.headers = header.id
          }
        )
      })
    })
}

